pub(crate) type Cl = m![Gg / 8];
pub(crate) type Sl = m![Gg % 8, Kc];
pub(crate) type SlOut = m![Gg % 8, 1 # 32];

/// x[Tb, Kc, Ke] (HBM, chunk-major with 2 zero chunks) -> every row group gets the whole x on its 32 chunk slices (DMA replication).
pub(crate) fn load_x(device: &mut Device, xn: &HbmTensor<bf16, Chip, m![Tb, Kc, Ke]>) -> DmTensor<bf16, Chip, Cl, Sl, m![Tb, Ke]> {
    xn.to_dm(&mut device.tdma)
}

